import React from 'react';

interface Discrepancy {
  type: string;
  drugName: string;
  refPrice?: number;
  invPrice?: number;
  percentOver?: string;
  refFormulation?: string;
  invFormulation?: string;
  refStrength?: string;
  invStrength?: string;
  refPayer?: string;
  invPayer?: string;
}


interface DiscrepancyDashboardProps {
  discrepancies: any[];
}

const getBadge = (type: string) => {
  switch (type) {
    case 'Unit Price': return <span style={{background: '#ffe0e0', color: '#a00', padding: '2px 8px', borderRadius: '5px'}}>Overcharge</span>;
    case 'Formulation': return <span style={{background: '#fff8dc', color: '#b8860b', padding: '2px 8px', borderRadius: '5px'}}>Billing Error</span>;
    case 'Strength': return <span style={{background: '#e0f7fa', color: '#00838f', padding: '2px 8px', borderRadius: '5px'}}>Safety Concern</span>;
    case 'Payer': return <span style={{background: '#e8eaf6', color: '#1a237e', padding: '2px 8px', borderRadius: '5px'}}>Claims Review</span>;
    default: return null;
  }
};

const DiscrepancyDashboard: React.FC<DiscrepancyDashboardProps> = ({ discrepancies }) => (
  <div style={{marginTop: 32}}>
    <h2>Discrepancies Summary</h2>
    {discrepancies.length === 0 ? <div>No issues detected.</div> :
    <table>
      <thead>
        <tr>
          <th>Type</th>
          <th>Drug Name</th>
          <th>Details</th>
          <th>Action</th>
        </tr>
      </thead>
      <tbody>
      {discrepancies.map((d, idx) => (
        <tr key={idx} style={{background: idx % 2 === 0 ? '#f8f8f8' : '#fff'}}>
          <td>{d.type}</td>
          <td>{d.drugName}</td>
          <td>
            {d.type === 'Unit Price' && `Invoice $${d.invPrice} vs Ref $${d.refPrice} (+${d.percentOver}%)`}
            {d.type === 'Formulation' && `Invoice "${d.invFormulation}", Ref "${d.refFormulation}"`}
            {d.type === 'Strength' && `Invoice "${d.invStrength}", Ref "${d.refStrength}"`}
            {d.type === 'Payer' && `Invoice "${d.invPayer}", Ref "${d.refPayer}"`}
          </td>
          <td>{getBadge(d.type)}</td>
        </tr>
      ))}
      </tbody>
    </table>
    }
  </div>
);

export default DiscrepancyDashboard;
export {};
